insert into public.pages (key, title, status, published_content, published_at) values ('home', 'Home', 'published', '{"hero":{"eyebrow":"Software development & digital innovation","headline":"We Build Digital Products That Make an Impact.","description":"From mobile apps to intelligent software solutions, we turn ambitious ideas into real digital experiences.","primaryCta":{"label":"Start a Project","href":"/contact"},"secondaryCta":{"label":"Explore Our Work","href":"/work"},"credibility":"Founded by an engineer with over 10 years of mobile app development experience.","backgroundImage":""},"sections":[{"key":"stats","visible":true,"heading":"Experience you can build on","description":"Figures marked as founder experience refer to our founder''s career, not only to ParitySoft AI.","items":[{"value":10,"suffix":"+","label":"Years of mobile development","note":"Founder''s experience","verified":true},{"value":50,"suffix":"+","label":"Applications worked on","note":"Founder''s experience","verified":true},{"value":24.2,"suffix":"K","label":"Total users","note":"Pending confirmation of scope and period","verified":false},{"value":200,"suffix":"+","label":"Active subscribers","note":"Pending confirmation of scope and period","verified":false}]},{"key":"services","visible":true,"heading":"End-to-End Software Development for a Digital-First World","description":"We design and build scalable, high-performance applications across mobile, desktop, and connected platforms."},{"key":"why","visible":true,"heading":"Built on Experience. Driven by Engineering.","description":"What you can expect when you work with us.","items":[{"title":"Native and cross-platform expertise","description":"Swift, Kotlin and Flutter under one roof, so the platform choice is made for your product, not for our convenience."},{"title":"Mobile and desktop engineering","description":"Experience across iOS, Android, macOS and Windows means your product can grow onto new devices."},{"title":"Practical product experience","description":"We build and maintain our own apps, so we understand releases, reviews, subscriptions and support."},{"title":"Thoughtful UI/UX","description":"Interfaces designed around real user flows, platform conventions and accessibility."},{"title":"Quality-focused development","description":"Code review, automated tests and staged releases are part of the process, not an add-on."},{"title":"Long-term maintainability","description":"Clear architecture and documentation so your product stays easy to change after launch."}]},{"key":"tech","visible":true,"heading":"Technology Expertise","description":"The languages, frameworks and tools we use every day — chosen for each product, not by habit."},{"key":"process","visible":true,"heading":"From Idea to Impact","description":"A clear, collaborative process with visible progress at every step.","items":[{"title":"Discover","description":"Understand business goals, users, requirements, and constraints."},{"title":"Plan","description":"Define scope, technical architecture, milestones, and delivery approach."},{"title":"Design","description":"Create user flows, interfaces, prototypes, and design systems."},{"title":"Develop","description":"Implement, integrate, review, and test the software."},{"title":"Launch & Improve","description":"Prepare releases, monitor quality, and support improvements."}]},{"key":"work","visible":true,"heading":"Featured Projects","description":"Selected projects, shown with the permission and attribution they require."},{"key":"products","visible":true,"heading":"Featured Products","description":"Beyond client development, we build and maintain our own digital products."},{"key":"proof","visible":true,"heading":"What clients say","fallbackHeading":"Founder-Led Engineering Experience","description":"The experience behind the work we deliver.","testimonials":[],"highlights":[{"title":"A decade of shipping mobile apps","description":"Our founder has worked on mobile applications for more than ten years, across native and cross-platform stacks."},{"title":"Publisher of our own products","description":"We design, release and support our own software, which keeps our process grounded in real-world results."},{"title":"Store-ready from day one","description":"App Store, Google Play and Microsoft Store requirements are planned for from the start of every project."}]},{"key":"cta","visible":true,"heading":"Ready to Bring Your Idea to Life?","description":"Whether you''re planning a mobile app, desktop solution, or intelligent software product, we''d love to hear about your project.","primaryCta":{"label":"Start a Project","href":"/contact"},"secondaryCta":{"label":"Contact Us","href":"/contact#details"}}]}'::jsonb, now()) on conflict (key) do nothing;
insert into public.pages (key, title, status, published_content, published_at) values ('about', 'About', 'published', '{"heading":"Engineering What''s Next.","intro":"ParitySoft AI is a software development company focused on mobile and desktop applications, AI-powered features and digital product engineering. We build software for clients and publish our own products.","mission":"Turn ambitious ideas into reliable, well-crafted software that people enjoy using and businesses can depend on.","vision":"Be a trusted engineering partner for teams worldwide, known for products that perform on every platform they run on.","blocks":[{"id":"about-h1","type":"heading","level":2,"text":"Our story"},{"id":"about-rt1","type":"richText","markdown":"ParitySoft AI was founded by a mobile engineer with more than ten years of experience building iOS, Android and cross-platform applications.\n\nThe name reflects how we work: **parity** between platforms, so your product feels equally good on every device, and between design and engineering, so what is designed is what ships."},{"id":"about-fg1","type":"featureGrid","heading":"How we work","items":[{"title":"Honest scoping","description":"We tell you what is realistic for your budget and timeline before work begins."},{"title":"Visible progress","description":"Regular builds you can install and try, not just status reports."},{"title":"Ownership","description":"You own the code, designs and accounts we create for your product."}]},{"id":"about-cta","type":"cta","heading":"Have a project in mind?","description":"Tell us about it and we''ll reply with next steps.","label":"Start a Project","href":"/contact"}]}'::jsonb, now()) on conflict (key) do nothing;
insert into public.pages (key, title, status, published_content, published_at) values ('contact', 'Contact', 'published', '{"heading":"Start a project","intro":"Tell us what you''re building. We read every inquiry and reply with questions or next steps — usually within two business days.","blocks":[{"id":"contact-faq","type":"faq","heading":"Before you get in touch","items":[{"question":"What should I include in my message?","answer":"Your goals, target platforms, any existing designs or code, and your timeline. Rough is fine."},{"question":"Do you sign NDAs?","answer":"Yes, we''re happy to sign a reasonable NDA before you share confidential details."}]}]}'::jsonb, now()) on conflict (key) do nothing;
insert into public.pages (key, title, status, published_content, published_at) values ('privacy', 'Privacy Policy', 'published', '{"heading":"Privacy Policy","intro":"How ParitySoft AI collects, uses and protects information submitted through this website.","notice":"Draft: this policy is a starting template and must be reviewed by a qualified legal professional before it is relied upon.","blocks":[{"id":"pp-1","type":"richText","markdown":"## Information we collect\n\nWhen you submit our contact form we collect the details you provide: your name, email address, company name (optional), the service you are interested in, optional budget and timeline preferences, and your project description.\n\nTo protect the form from abuse we store a one-way hash of your IP address for a limited time. We do not store your raw IP address alongside your inquiry.\n\nWe use privacy-friendly website analytics to understand aggregate page usage. These analytics do not use cookies to identify you personally.\n\n## How we use your information\n\n- To respond to your inquiry and discuss your project\n- To keep a record of business communications\n- To protect our website from spam and abuse\n\nWe do not sell your personal information.\n\n## Retention\n\nInquiries are retained only as long as needed to respond and maintain business records, after which they are deleted.\n\n## Service providers\n\nWe use third-party providers to host this website, store data and send email notifications. They process data on our behalf under their own security and privacy commitments.\n\n## Your rights\n\nYou may ask us to access, correct or delete the personal information you have submitted. Contact us using the details on our contact page.\n\n## Changes\n\nWe may update this policy. The latest version will always be published on this page."}]}'::jsonb, now()) on conflict (key) do nothing;
insert into public.pages (key, title, status, published_content, published_at) values ('terms', 'Terms of Use', 'published', '{"heading":"Terms of Use","intro":"The terms that apply when you use the parisoftai.com website.","notice":"Draft: these terms are a starting template and must be reviewed by a qualified legal professional before they are relied upon.","blocks":[{"id":"tos-1","type":"richText","markdown":"## Use of this website\n\nThis website provides information about ParitySoft AI and its services and products. You may browse it for personal and business purposes.\n\n## Intellectual property\n\nUnless stated otherwise, the content, design and code of this website belong to ParitySoft AI. Product names and trademarks of third parties belong to their respective owners.\n\n## No warranty\n\nInformation on this website is provided in good faith but without warranty. Project terms are agreed separately in writing.\n\n## Third-party links\n\nThis website may link to app stores and other external sites. We are not responsible for their content.\n\n## Changes\n\nWe may update these terms. Continued use of the website means you accept the current version."}]}'::jsonb, now()) on conflict (key) do nothing;
insert into public.services (slug, title, short_description, full_description, icon, problems, features, benefits, approach, technologies, faq, seo_title, seo_description, sort_order, status) values ('ios-app-development', 'iOS App Development', 'Native iPhone and iPad apps built with Swift and SwiftUI that feel at home on Apple platforms and pass App Store review cleanly.', 'We build native iOS apps in Swift and SwiftUI, following Apple''s Human Interface Guidelines so your product behaves the way iPhone users expect. From the first prototype to App Store submission, we focus on smooth performance, accessibility, and a codebase your team can keep extending.', 'apple', array['Your app needs to feel genuinely native, not like a web page wrapped in a shell.', 'You need features that depend on Apple frameworks such as HealthKit, StoreKit, widgets, or push notifications.', 'An existing iOS codebase has become hard to change and slow to release.', 'You are unsure how to get through App Store review and subscription setup.']::text[], '[{"title":"SwiftUI interfaces","description":"Modern declarative UI with support for Dynamic Type, Dark Mode and VoiceOver."},{"title":"Platform integrations","description":"Widgets, notifications, in-app purchases, Sign in with Apple, and system frameworks."},{"title":"Offline-ready data","description":"Local persistence and sync strategies that keep the app usable on poor connections."},{"title":"Release management","description":"TestFlight builds, App Store Connect setup, metadata, and review preparation."}]'::jsonb, array['Native performance and platform conventions users already understand', 'Direct access to the latest Apple APIs as they ship', 'A maintainable architecture that scales with new features']::text[], '[{"title":"Product discovery","description":"Clarify users, core flows, and the Apple capabilities the app depends on."},{"title":"Architecture","description":"Choose data, networking and state patterns (typically MVVM) before writing features."},{"title":"Iterative builds","description":"Ship TestFlight builds regularly so you can try real features early."},{"title":"Launch","description":"Prepare App Store assets, privacy details and submission, then support the release."}]'::jsonb, array['Swift', 'SwiftUI', 'UIKit', 'Combine', 'Swift Concurrency', 'Core Data', 'SwiftData', 'StoreKit', 'XCTest']::text[], '[{"question":"Should I build native iOS or cross-platform?","answer":"Native is the stronger choice when your product depends on Apple-specific features, demanding performance, or a premium iOS feel. If you need iOS and Android quickly with a shared codebase, Flutter is often more cost-effective. We''ll recommend one after understanding your requirements."},{"question":"Do you handle App Store submission?","answer":"Yes. We prepare builds, App Store Connect configuration, screenshots and privacy disclosures, and we help you respond to any review feedback."},{"question":"Can you take over an existing iOS app?","answer":"Yes. We start with a code review to understand its current state, then propose a practical plan for fixes, modernization and new features."}]'::jsonb, 'iOS App Development | Swift & SwiftUI', 'Native iPhone and iPad app development with Swift and SwiftUI — from product discovery to App Store launch and ongoing support.', 10, 'published') on conflict (slug) do nothing;
insert into public.services (slug, title, short_description, full_description, icon, problems, features, benefits, approach, technologies, faq, seo_title, seo_description, sort_order, status) values ('android-app-development', 'Android App Development', 'Native Android apps in Kotlin and Jetpack Compose, designed for the wide range of devices your users actually own.', 'We develop native Android applications in Kotlin with Jetpack Compose and Material 3. Our focus is reliable behavior across screen sizes and OS versions, efficient battery and network use, and a clean architecture that keeps features easy to add.', 'smartphone', array['Your app must work well across many devices, screen sizes and Android versions.', 'You need deep Android integrations such as background work, notifications or hardware access.', 'Crash rates or ANRs are hurting your Play Store ratings.', 'A legacy Java or XML-based app needs a modern foundation.']::text[], '[{"title":"Jetpack Compose UI","description":"Material 3 interfaces with adaptive layouts for phones, foldables and tablets."},{"title":"Clean architecture","description":"MVVM, dependency injection with Hilt, and clear separation of data and UI layers."},{"title":"Background & sync","description":"WorkManager, notifications and offline-first data with Room."},{"title":"Play Store release","description":"Signing, staged rollouts, store listing and policy compliance."}]'::jsonb, array['Consistent experience across a fragmented device landscape', 'Lower crash rates through careful lifecycle and state handling', 'A modern Kotlin codebase that is straightforward to maintain']::text[], '[{"title":"Requirements","description":"Map user flows, target devices and minimum Android version."},{"title":"Architecture","description":"Set up modules, DI and data layers before feature work begins."},{"title":"Build & test","description":"Develop in short iterations with internal test tracks for early feedback."},{"title":"Release","description":"Staged rollout on Google Play with monitoring of crashes and performance."}]'::jsonb, array['Kotlin', 'Jetpack Compose', 'Material 3', 'Coroutines', 'Flow', 'Hilt', 'Room', 'WorkManager', 'Retrofit']::text[], '[{"question":"Can you migrate our Java/XML app to Kotlin and Compose?","answer":"Yes. We usually migrate incrementally, screen by screen, so the app keeps shipping while the codebase is modernized."},{"question":"Which Android versions will you support?","answer":"We recommend a minimum version based on your audience and required APIs, balancing reach against development and testing cost."}]'::jsonb, 'Android App Development | Kotlin & Compose', 'Native Android app development with Kotlin, Jetpack Compose and Material 3 — reliable across devices and ready for Google Play.', 20, 'published') on conflict (slug) do nothing;
insert into public.services (slug, title, short_description, full_description, icon, problems, features, benefits, approach, technologies, faq, seo_title, seo_description, sort_order, status) values ('flutter-app-development', 'Flutter Cross-Platform Development', 'One Flutter codebase for iOS, Android and beyond — faster delivery without giving up a polished, consistent interface.', 'Flutter lets us ship a single, well-structured Dart codebase to iOS and Android, with desktop and web targets available when needed. We use proven state-management patterns and platform channels so your app stays fast, testable and able to use native features.', 'layers', array['You need iOS and Android at the same time on a realistic budget.', 'Keeping two native codebases in sync is slowing your team down.', 'You want a custom, branded UI that looks identical on every platform.', 'An existing Flutter app has grown hard to maintain.']::text[], '[{"title":"Shared codebase","description":"One Dart codebase for iOS and Android, with optional macOS, Windows and web targets."},{"title":"Structured state","description":"Riverpod or BLoC with clear layers, making features predictable and testable."},{"title":"Native bridges","description":"Platform channels and plugins for device features when packages aren''t enough."},{"title":"Automated testing","description":"Unit, widget and integration tests to protect releases."}]'::jsonb, array['Shorter time to market on both major mobile platforms', 'One team and one codebase to maintain', 'Pixel-consistent branding across devices']::text[], '[{"title":"Scope","description":"Confirm which platforms and native features the product needs."},{"title":"Foundation","description":"Set up architecture, theming, navigation and CI."},{"title":"Feature delivery","description":"Build in iterations with test builds for both platforms."},{"title":"Store launch","description":"Release to App Store and Google Play together."}]'::jsonb, array['Flutter', 'Dart', 'Riverpod', 'BLoC', 'go_router', 'Firebase', 'Platform Channels']::text[], '[{"question":"Is Flutter good enough for production apps?","answer":"Yes, for most product categories. It is less suitable when an app depends heavily on cutting-edge platform-specific APIs, which we''ll flag during discovery."},{"question":"Can a Flutter app also run on desktop?","answer":"Flutter supports macOS, Windows and Linux. We''ll assess whether your plugins and UI patterns translate well to desktop before committing to it."}]'::jsonb, 'Flutter App Development | Cross-Platform', 'Cross-platform Flutter and Dart app development for iOS and Android from one maintainable codebase.', 30, 'published') on conflict (slug) do nothing;
insert into public.services (slug, title, short_description, full_description, icon, problems, features, benefits, approach, technologies, faq, seo_title, seo_description, sort_order, status) values ('desktop-app-development', 'macOS & Windows Applications', 'Desktop software for macOS and Windows that respects each platform''s conventions and handles real productivity workloads.', 'We build desktop applications for macOS and Windows — native where platform integration matters, cross-platform where a shared codebase makes more sense. Typical work includes productivity tools, utilities, companion apps for mobile products and internal business software.', 'monitor', array['Your users work on desktops and need more than a browser tab can offer.', 'You need file system access, menu bar or system tray presence, or offline operation.', 'You want your mobile product to have a matching desktop companion.', 'Distribution, code signing and updates feel complicated.']::text[], '[{"title":"Native macOS","description":"SwiftUI and AppKit apps including menu bar utilities and document-based apps."},{"title":"Windows apps","description":"Modern Windows applications with packaging for the Microsoft Store or direct distribution."},{"title":"Shared logic","description":"Cross-platform options such as Flutter desktop when one codebase fits best."},{"title":"Distribution","description":"Code signing, notarization, installers and update strategies."}]'::jsonb, array['Software that feels native on each operating system', 'Offline capability and deep OS integration', 'A clear plan for signing, distribution and updates']::text[], '[{"title":"Platform fit","description":"Decide between native and shared codebases based on features and budget."},{"title":"Design","description":"Adapt layouts and interactions to desktop conventions such as menus and keyboard shortcuts."},{"title":"Build","description":"Develop and test on each target OS throughout the project."},{"title":"Ship","description":"Sign, notarize, package and publish through the right stores or channels."}]'::jsonb, array['Swift', 'SwiftUI', 'AppKit', 'C#', '.NET', 'WinUI', 'Flutter Desktop']::text[], '[{"question":"Can you publish to the Mac App Store and Microsoft Store?","answer":"Yes. We can also set up direct distribution with signed installers when store distribution is not the right fit."}]'::jsonb, 'macOS & Windows Desktop App Development', 'Desktop application development for macOS and Windows — native or cross-platform, signed, packaged and ready to distribute.', 40, 'published') on conflict (slug) do nothing;
insert into public.services (slug, title, short_description, full_description, icon, problems, features, benefits, approach, technologies, faq, seo_title, seo_description, sort_order, status) values ('backend-development', 'Backend & API Development', 'Secure REST APIs, authentication and cloud backends that give your apps reliable data, accounts and integrations.', 'Apps are only as dependable as the systems behind them. We design and build backends and REST APIs with clear contracts, sensible security and room to grow — using managed platforms such as Supabase or Firebase where they fit, and custom Node.js services where they don''t.', 'server', array['Your app needs user accounts, data sync or subscriptions handled securely.', 'You must integrate payment providers, third-party APIs or internal systems.', 'An existing backend is slow, hard to change or poorly documented.', 'You are unsure which cloud services to use and what they will cost.']::text[], '[{"title":"API design","description":"Documented REST APIs with validation, versioning and consistent error handling."},{"title":"Auth & security","description":"Authentication, role-based access and secure secret management."},{"title":"Data modeling","description":"PostgreSQL schemas, migrations and row-level security where appropriate."},{"title":"Integrations","description":"Payments, email, push notifications and third-party services."}]'::jsonb, array['A dependable foundation for mobile, desktop and web clients', 'Security built in from the start rather than bolted on', 'Infrastructure choices matched to your scale and budget']::text[], '[{"title":"Requirements","description":"Define data, integrations, access rules and expected load."},{"title":"Design","description":"Model the schema and API contract before implementation."},{"title":"Implement","description":"Build with automated tests, migrations and environment separation."},{"title":"Operate","description":"Deploy with monitoring, backups and documentation."}]'::jsonb, array['Node.js', 'TypeScript', 'PostgreSQL', 'Supabase', 'Firebase', 'REST', 'Docker']::text[], '[{"question":"Do you work with our existing backend?","answer":"Yes. We can integrate apps with your current APIs, or help improve and extend them after reviewing the existing system."}]'::jsonb, 'Backend & REST API Development', 'Secure backend and REST API development with Node.js, PostgreSQL, Supabase and Firebase for mobile and desktop apps.', 50, 'published') on conflict (slug) do nothing;
insert into public.services (slug, title, short_description, full_description, icon, problems, features, benefits, approach, technologies, faq, seo_title, seo_description, sort_order, status) values ('ai-integration', 'AI Integration', 'Practical AI features — assistants, smart search, summarization and on-device intelligence — added where they genuinely help users.', 'We help you add AI capabilities to new and existing apps in ways that are useful, measurable and responsible. That can mean integrating large language model APIs, building retrieval over your own content, or running models on-device for privacy and speed.', 'sparkles', array['You want to add AI to your product but are unsure where it creates real value.', 'Users need to search, summarize or ask questions about large amounts of content.', 'Privacy requirements mean some data should never leave the device.', 'You need to control AI costs, latency and output quality.']::text[], '[{"title":"LLM features","description":"Chat, drafting, summarization and classification using leading model APIs."},{"title":"Retrieval (RAG)","description":"Answers grounded in your own documents and data, with source references."},{"title":"On-device ML","description":"Core ML, ML Kit and lightweight models for private, offline features."},{"title":"Guardrails","description":"Input/output validation, rate limits, cost controls and evaluation."}]'::jsonb, array['AI features scoped to clear user outcomes', 'Server-side key management and data-handling safeguards', 'Measurable quality through evaluation before and after launch']::text[], '[{"title":"Use-case review","description":"Identify tasks where AI measurably improves the user experience."},{"title":"Prototype","description":"Test feasibility, quality and cost on real examples."},{"title":"Integrate","description":"Build the feature into your app with security and fallbacks."},{"title":"Evaluate","description":"Monitor quality, latency and cost, and iterate."}]'::jsonb, array['LLM APIs', 'RAG', 'Embeddings', 'Core ML', 'ML Kit', 'TensorFlow Lite', 'Python']::text[], '[{"question":"Will our data be used to train AI models?","answer":"We select providers and configurations based on your data-handling requirements and document how data flows. Provider terms vary, so we review them with you before integration."},{"question":"Can AI run without an internet connection?","answer":"Some features can run on-device using smaller models. We''ll tell you which of your use cases are realistic offline."}]'::jsonb, 'AI Integration for Mobile & Desktop Apps', 'Add practical AI features to your apps — LLM integrations, retrieval over your content and on-device machine learning.', 60, 'published') on conflict (slug) do nothing;
insert into public.services (slug, title, short_description, full_description, icon, problems, features, benefits, approach, technologies, faq, seo_title, seo_description, sort_order, status) values ('ui-ux-design', 'UI/UX Design', 'User flows, interfaces and design systems that make your product easy to understand and pleasant to use.', 'Good engineering needs a clear design to build against. We map user journeys, create wireframes and high-fidelity interfaces, and assemble design systems that keep your product consistent as it grows — always with accessibility and real implementation constraints in mind.', 'pen-tool', array['Users get lost or drop off in key flows such as onboarding or checkout.', 'Your product looks inconsistent across screens and platforms.', 'Developers lack a clear, complete design to build from.', 'You need to validate an idea before investing in full development.']::text[], '[{"title":"UX research & flows","description":"User journeys, information architecture and wireframes."},{"title":"Interface design","description":"High-fidelity screens for mobile, desktop and web."},{"title":"Prototypes","description":"Clickable prototypes to test ideas with stakeholders and users."},{"title":"Design systems","description":"Reusable components, tokens and documentation for consistent delivery."}]'::jsonb, array['Clearer products that need less explaining', 'Faster development thanks to complete, consistent specs', 'Accessibility considered from the first wireframe']::text[], '[{"title":"Understand","description":"Learn about your users, goals and constraints."},{"title":"Structure","description":"Define flows and wireframes before visual design."},{"title":"Design","description":"Create interfaces and a component library."},{"title":"Hand off","description":"Deliver specs and support developers during implementation."}]'::jsonb, array['Figma', 'Design Systems', 'Prototyping', 'Human Interface Guidelines', 'Material Design', 'WCAG']::text[], '[{"question":"Can you design only, without developing?","answer":"Yes. We can deliver designs and a design system for your own team to implement."}]'::jsonb, 'UI/UX Design for Apps & Software', 'UI/UX design for mobile and desktop apps — user flows, interfaces, prototypes and design systems built for implementation.', 70, 'published') on conflict (slug) do nothing;
insert into public.services (slug, title, short_description, full_description, icon, problems, features, benefits, approach, technologies, faq, seo_title, seo_description, sort_order, status) values ('app-maintenance-modernization', 'Application Maintenance & Support', 'Keep existing apps healthy — OS updates, bug fixes, performance work and gradual modernization of older codebases.', 'Software needs care after launch. We keep apps compatible with new OS releases and store policies, fix bugs, improve performance, and modernize aging code in manageable steps so your product keeps moving without risky rewrites.', 'wrench', array['New iOS or Android versions keep breaking your app.', 'Store policy changes or deprecated SDKs threaten your listing.', 'The original developers are gone and nobody understands the code.', 'Performance and crash rates are slowly getting worse.']::text[], '[{"title":"Code audit","description":"An honest assessment of code health, risks and priorities."},{"title":"OS & SDK updates","description":"Compatibility work for new platform releases and policy requirements."},{"title":"Stability & performance","description":"Crash fixing, profiling and optimization."},{"title":"Incremental modernization","description":"Step-by-step migration to current languages and frameworks."}]'::jsonb, array['Fewer surprises at each OS release', 'Lower long-term cost than a full rewrite', 'A codebase your team can understand again']::text[], '[{"title":"Audit","description":"Review the codebase, build pipeline and crash data."},{"title":"Stabilize","description":"Fix the highest-impact issues first."},{"title":"Modernize","description":"Improve architecture and dependencies incrementally."},{"title":"Support","description":"Ongoing updates on an agreed schedule."}]'::jsonb, array['Swift', 'Kotlin', 'Flutter', 'Objective-C', 'Java', 'CI/CD', 'Crash Reporting']::text[], '[{"question":"Do you offer ongoing maintenance agreements?","answer":"Yes. After an initial audit we can agree on a scope and schedule that fits your product''s needs."}]'::jsonb, 'App Maintenance & Modernization', 'Mobile and desktop app maintenance — OS updates, bug fixing, performance work and incremental modernization.', 80, 'published') on conflict (slug) do nothing;
