insert into public.site_settings (key, value) values ('contact_form', '{"budgetOptions":["Under $5,000","$5,000 – $15,000","$15,000 – $40,000","$40,000+","Not sure yet"],"timelineOptions":["As soon as possible","1–3 months","3–6 months","6+ months","Flexible"],"consentText":"I agree that ParitySoft AI may store the information I submit so it can respond to my inquiry.","retentionDays":730}'::jsonb) on conflict (key) do nothing;
